c=Page('08-fem-controls','Optional FEM control level translation and safe defaults')
box(c,20,18,'Pack-referenced control outputs / default shutdown','SKY66423 requires controls near GND or VCC0 for specified sleep current.\n3.3 V GPIO is not a full-height logic high when PACK+ is 4.05 V.\nTwo-transistor level translation gives non-inverting 0 / PACK+ outputs.\nDefault MCU reset state keeps all three FEM controls LOW; no floating mode pins.')
for i,(src,dst) in enumerate([('FEM_CSD','CSD_PACK'),('FEM_CTX','CTX_PACK'),('FEM_CPS','CPS_PACK')]):
    global_nets.add(dst);x=60.96+i*116.84;px=60+i*9
    c.add('Q'+str(601+i*2),'Q_NMOS_GSD','2N7002','Node:SOT23',x,101.6,{1:src,2:'GND',3:dst+'_INV'},dnp=True,pcb=[px,50,0],group='FEM')
    c.add('Q'+str(602+i*2),'Q_PMOS_GSD','BSS84','Node:SOT23',x+40.64,157.48,{1:dst+'_INV',2:'PACK_P',3:dst+'_DRV'},dnp=True,pcb=[px+4,50,0],group='FEM')
    for j,(val,a,b,xx,yy,xy) in enumerate([('1M',src,'GND',x-25.4,142.24,[px,53,90]),('1M','PACK_P',dst+'_INV',x+20.32,73.66,[px+2,47,90]),('1k',dst+'_DRV',dst,x+45.72,119.38,[px+4,47,90]),('1M',dst,'GND',x+45.72,203.2,[px+4,53,90])]):
        comp(c,'R'+str(611+i*4+j),val,a,b,xx,yy,xy,rot=0,dnp=True,group='FEM')
    tp(c,'TP'+str(601+i),dst,x+20.32,233.68,[px+6,55,0])
box(c,25,257,'Current audit','LOW outputs have no DC resistor current. A HIGH output draws ~8uA through\nthe gate pullup and output pulldown at PACK=4.05V. Allow >=1ms settling after\nmode changes. Qualify transistor leakage and FEM shutdown current on the bench.')
